"""Historique global des répertoires d'artefacts screener pour l'IHM."""
from __future__ import annotations

from pathlib import Path
from typing import Any

from ihm.services.backtesting_registry import load_backtesting_history
from ihm.services.pipeline_runner import PROJECT_ROOT
from ihm.services.screener_recommendations import (
    DEFAULT_SCREENER_ARTIFACTS_DIR,
    build_screener_artifact_summary,
    get_screener_artifacts_dir,
)

SHARED_SELECTED_SCREENER_ARTIFACTS_DIR_KEY = "ihm_selected_screener_artifacts_dir"
SCREENER_RUN_KINDS = frozenset({"diagnose-screener", "recommend-screener"})


def normalize_screener_artifacts_dir(artifacts_dir: Path | str | None = None) -> str:
    return str(get_screener_artifacts_dir(artifacts_dir))


def _artifacts_dir_label(artifacts_dir: str) -> str:
    path = Path(artifacts_dir)
    try:
        return str(path.relative_to(PROJECT_ROOT))
    except ValueError:
        return str(path)


def _last_run_timestamp(run_record: dict[str, object]) -> str:
    return str(run_record.get("finished_at") or run_record.get("executed_at") or "")


def _history_sort_key(entry: dict[str, Any]) -> tuple[str, str, str]:
    summary = entry.get("summary") if isinstance(entry.get("summary"), dict) else {}
    updated_at_iso = str(summary.get("updated_at_iso") or "")
    last_run_at = str(entry.get("last_run_at") or "")
    is_default = "1" if str(entry.get("artifacts_dir", "")) == normalize_screener_artifacts_dir(DEFAULT_SCREENER_ARTIFACTS_DIR) else "0"
    return (max(updated_at_iso, last_run_at), is_default, str(entry.get("artifacts_dir", "")))


def build_screener_history_entry(
    artifacts_dir: Path | str,
    *,
    runs: list[dict[str, object]] | None = None,
    source_tags: list[str] | set[str] | tuple[str, ...] | None = None,
) -> dict[str, Any]:
    normalized_dir = normalize_screener_artifacts_dir(artifacts_dir)
    ordered_runs = sorted(runs or [], key=_last_run_timestamp, reverse=True)
    last_run = ordered_runs[0] if ordered_runs else {}
    summary = build_screener_artifact_summary(normalized_dir)
    return {
        "artifacts_dir": normalized_dir,
        "artifacts_dir_label": _artifacts_dir_label(normalized_dir),
        "available": bool(summary.get("available")),
        "coverage_label": str(summary.get("coverage_label") or "Période non renseignée"),
        "updated_at_label": str(summary.get("updated_at_label") or "inconnue"),
        "baseline_name": summary.get("baseline_name"),
        "objective_count": int(summary.get("objective_count") or 0),
        "scenario_count": int(summary.get("scenario_count") or 0),
        "file_count": int(summary.get("file_count") or 0),
        "market_regime_count": len(summary.get("market_regimes", []))
        if isinstance(summary.get("market_regimes"), list)
        else 0,
        "diagnostic_available": bool(summary.get("diagnostic_available")),
        "recommendation_available": bool(summary.get("recommendation_available")),
        "regime_analysis_available": bool(summary.get("regime_analysis_available")),
        "run_count": len(ordered_runs),
        "last_run_id": last_run.get("run_id"),
        "last_run_label": last_run.get("run_label") or last_run.get("run_kind"),
        "last_run_kind": last_run.get("run_kind"),
        "last_run_status": last_run.get("status"),
        "last_run_at": _last_run_timestamp(last_run) if last_run else "",
        "source_tags": sorted({str(value) for value in (source_tags or []) if str(value).strip()}),
        "summary": summary,
    }


def build_global_screener_artifact_history(
    additional_dirs: list[Path | str] | None = None,
) -> list[dict[str, Any]]:
    grouped_runs: dict[str, list[dict[str, object]]] = {}
    source_tags: dict[str, set[str]] = {}

    def register_dir(raw_dir: Path | str | None, *, source_tag: str) -> None:
        if raw_dir is None:
            return
        text = str(raw_dir).strip()
        if not text:
            return
        normalized = normalize_screener_artifacts_dir(text)
        grouped_runs.setdefault(normalized, [])
        source_tags.setdefault(normalized, set()).add(source_tag)

    register_dir(DEFAULT_SCREENER_ARTIFACTS_DIR, source_tag="défaut")

    for run in load_backtesting_history():
        if str(run.get("run_kind", "")) not in SCREENER_RUN_KINDS:
            continue
        artifacts_dir = run.get("screener_artifacts_dir")
        if not artifacts_dir:
            continue
        normalized = normalize_screener_artifacts_dir(str(artifacts_dir))
        grouped_runs.setdefault(normalized, []).append(run)
        source_tags.setdefault(normalized, set()).add("runs IHM")

    for extra_dir in additional_dirs or []:
        register_dir(extra_dir, source_tag="sélection manuelle")

    entries: list[dict[str, Any]] = []
    for artifacts_dir, runs in grouped_runs.items():
        entries.append(build_screener_history_entry(artifacts_dir, runs=runs, source_tags=source_tags.get(artifacts_dir, set())))

    entries.sort(key=_history_sort_key, reverse=True)
    return entries


def resolve_selected_screener_artifacts_dir(
    history_entries: list[dict[str, Any]],
    preferred_dir: Path | str | None = None,
    *,
    missing_source_tag: str = "préférence persistée",
) -> tuple[str, dict[str, dict[str, Any]]]:
    entry_map = {
        str(entry.get("artifacts_dir", "")): entry
        for entry in history_entries
        if str(entry.get("artifacts_dir", "")).strip()
    }
    selected_dir = ""
    if preferred_dir is not None and str(preferred_dir).strip():
        selected_dir = normalize_screener_artifacts_dir(preferred_dir)
        if selected_dir not in entry_map:
            entry_map[selected_dir] = build_screener_history_entry(selected_dir, source_tags=[missing_source_tag])

    if not entry_map:
        selected_dir = normalize_screener_artifacts_dir(DEFAULT_SCREENER_ARTIFACTS_DIR)
        entry_map[selected_dir] = build_screener_history_entry(selected_dir, source_tags=["défaut"])

    if not selected_dir or selected_dir not in entry_map:
        selected_dir = next(iter(entry_map.keys()))
    return selected_dir, entry_map


def format_screener_artifact_history_label(entry: dict[str, Any]) -> str:
    parts = [str(entry.get("artifacts_dir_label") or entry.get("artifacts_dir") or "répertoire inconnu")]
    if entry.get("recommendation_available"):
        parts.append(f"obj={int(entry.get('objective_count') or 0)}")
    if entry.get("coverage_label"):
        parts.append(str(entry.get("coverage_label")))
    if entry.get("updated_at_label"):
        parts.append(f"MAJ {entry.get('updated_at_label')}")
    run_count = int(entry.get("run_count") or 0)
    if run_count:
        parts.append(f"runs={run_count}")
    return " | ".join(parts)


def build_screener_artifact_history_rows(entries: list[dict[str, Any]]) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    for entry in entries:
        rows.append(
            {
                "Répertoire": entry.get("artifacts_dir_label") or entry.get("artifacts_dir") or "—",
                "Disponible": "oui" if bool(entry.get("available")) else "non",
                "Couverture": entry.get("coverage_label") or "Période non renseignée",
                "MAJ": entry.get("updated_at_label") or "inconnue",
                "Baseline": entry.get("baseline_name") or "—",
                "Reco objectifs": int(entry.get("objective_count") or 0),
                "Scénarios": int(entry.get("scenario_count") or 0),
                "Fichiers": int(entry.get("file_count") or 0),
                "Régimes": int(entry.get("market_regime_count") or 0),
                "Runs IHM": int(entry.get("run_count") or 0),
                "Dernier run": entry.get("last_run_label") or "—",
                "Statut": entry.get("last_run_status") or "—",
                "Origines": ", ".join(str(value) for value in entry.get("source_tags", []) if str(value).strip()) or "—",
                "Chemin": entry.get("artifacts_dir") or "—",
            }
        )
    return rows


__all__ = [
    "SCREENER_RUN_KINDS",
    "SHARED_SELECTED_SCREENER_ARTIFACTS_DIR_KEY",
    "build_global_screener_artifact_history",
    "build_screener_history_entry",
    "build_screener_artifact_history_rows",
    "format_screener_artifact_history_label",
    "normalize_screener_artifacts_dir",
    "resolve_selected_screener_artifacts_dir",
]

"""Préférences persistantes IHM liées à la navigation screener."""
from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any

from ihm.services.pipeline_runner import PROJECT_ROOT
from ihm.services.screener_recommendations import get_screener_artifacts_dir

PREFERENCES_DIR = PROJECT_ROOT / "artifacts" / "ihm_preferences"
SCREENER_SELECTION_PREFERENCES_PATH = PREFERENCES_DIR / "screener_selection.json"


def _ensure_storage() -> None:
    PREFERENCES_DIR.mkdir(parents=True, exist_ok=True)


def _normalize_optional_dir(artifacts_dir: Path | str | None) -> str | None:
    if artifacts_dir is None:
        return None
    text = str(artifacts_dir).strip()
    if not text:
        return None
    return str(get_screener_artifacts_dir(text))


def load_persisted_selected_screener_artifacts_dir() -> str | None:
    path = SCREENER_SELECTION_PREFERENCES_PATH
    if not path.exists() or not path.is_file():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8") or "{}")
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    return _normalize_optional_dir(payload.get("selected_screener_artifacts_dir"))


def save_persisted_selected_screener_artifacts_dir(artifacts_dir: Path | str | None) -> str | None:
    normalized_dir = _normalize_optional_dir(artifacts_dir)
    _ensure_storage()
    payload: dict[str, Any] = {
        "selected_screener_artifacts_dir": normalized_dir,
        "updated_at": datetime.now().isoformat(timespec="seconds"),
    }
    SCREENER_SELECTION_PREFERENCES_PATH.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return normalized_dir


__all__ = [
    "PREFERENCES_DIR",
    "SCREENER_SELECTION_PREFERENCES_PATH",
    "load_persisted_selected_screener_artifacts_dir",
    "save_persisted_selected_screener_artifacts_dir",
]

from ihm.pages import backtesting
def test_pages_backtesting_importable() -> None: assert hasattr(backtesting, "__doc__")
def test_parameter_reference_rows_include_screener_commands() -> None: diagnose_rows = backtesting._parameter_reference_rows("diagnose-screener") recommend_rows = backtesting._parameter_reference_rows("recommend-screener")
assert any(row["Paramètre"] == "output_dir" for row in diagnose_rows) assert any(row["Paramètre"] == "max_scenarios" for row in diagnose_rows) assert any(row["Paramètre"] == "input_dir" for row in recommend_rows) assert any(row["Paramètre"] == "target_horizon" for row in recommend_rows)

from ihm.pages import overview

def test_pages_overview_importable():
    assert hasattr(overview, "__doc__")


def test_build_pipeline_summary_rows_exposes_latest_workflow_and_upstream_runs() -> None:
    runs = [
        {
            "run_id": "wf-1",
            "run_kind": "workflow",
            "step_key": "pipeline_workflow",
            "status": "completed",
            "run_summary": {"workflow_steps_with_summary": 2, "targeted_symbols": 6, "successful_symbols": 5},
        },
        {
            "run_id": "imp-1",
            "run_kind": "step",
            "step_key": "import_alpaca_bar",
            "status": "completed",
            "run_summary": {"targeted_symbols": 3, "successful_symbols": 2},
        },
        {
            "run_id": "san-1",
            "run_kind": "step",
            "step_key": "data_sanitizer_daily",
            "status": "completed",
            "run_summary": {"targeted_symbols": 3, "successful_symbols": 3},
        },
    ]

    rows = overview._build_pipeline_summary_rows(runs)

    assert list(rows["scope"]) == ["Workflow complet", "Import Alpaca Bar", "Data Sanitizer Daily"]


def test_build_screener_objective_rows_exposes_operational_leaders() -> None:
    rows = overview._build_screener_objective_rows(
        {
            "objective_rows_df": overview.pd.DataFrame(
                [
                    {
                        "objective": "robust",
                        "objective_label": "robuste",
                        "scenario_name": "steady",
                        "objective_scope": "cross_regime",
                        "objective_score": 0.77,
                        "overall_score": 0.75,
                    }
                ]
            )
        }
    )

    assert list(rows.columns) == ["objectif", "label", "scénario", "périmètre", "score objectif", "score global"]
    assert rows.iloc[0]["scénario"] == "steady"

